using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Shared configuration for eval scenarios: chat client, evaluators, reporting.
/// </summary>
internal static class EvalConfig
{
    private static readonly string ModelEndpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com/";

    private static readonly string ModelDeployment =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
        ?? "gpt-4o-mini";

    /// <summary>
    /// Creates a chat client backed by Azure OpenAI, with telemetry enabled.
    /// </summary>
    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(ModelEndpoint), new Azure.AzureKeyCredential(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key"));

        return client
            .GetChatClient(ModelDeployment)
            .AsIChatClient()
            .AsBuilder()
            .UseOpenTelemetry()
            .Build();
    }

    /// <summary>
    /// Returns the set of quality evaluators (no safety evaluators).
    /// </summary>
    public static IList<IEvaluator> GetQualityEvaluators()
    {
        var judge = CreateChatClient();
        return
        [
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
            new CompletenessEvaluator(),
        ];
    }

    /// <summary>
    /// Builds a ReportingConfiguration that persists results to disk for comparison across runs.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(string scenarioName)
    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvalConfig).Assembly.Location)!,
            ".eval-results");

        return new ReportingConfiguration(
            storageRootPath: storageDir,
            evaluators: GetQualityEvaluators(),
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            enableResponseCaching: true);
    }

    /// <summary>
    /// Configures OpenTelemetry tracing for eval runs (console + OTLP).
    /// </summary>
    public static TracerProvider BuildTelemetryProvider()
    {
        return Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Coach")
            .AddConsoleExporter()
            .AddOtlpExporter()
            .Build()!;
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: verifies that AI interactions produce OpenTelemetry spans.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpans()
    {
        var exportedSpans = new List<System.Diagnostics.Activity>();

        using var tracer = EvalConfig.BuildTelemetryProvider();
        var client = EvalConfig.CreateChatClient();

        var response = await client.GetResponseAsync("What is 2+2?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0, "Expected at least one response message.");
    }

    [TestMethod]
    public async Task StreamingChatCompletion_EmitsTraceSpans()
    {
        using var tracer = EvalConfig.BuildTelemetryProvider();
        var client = EvalConfig.CreateChatClient();

        var chunks = new List<string>();
        await foreach (var update in client.GetStreamingResponseAsync("Say hello."))
        {
            if (update.Text is not null)
                chunks.Add(update.Text);
        }

        Assert.IsTrue(chunks.Count > 0, "Expected streaming chunks.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates response quality using LLM-as-judge metrics.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration s_config = null!;

    [ClassInitialize]
    public static void ClassInit(TestContext context)
    {
        s_config = EvalConfig.CreateReportingConfig("quality");
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync(
            scenarioName: "coach-basic-advice");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How do I improve my morning routine for productivity?")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        scenario.Record(response);

        await scenario.EvaluateAsync();

        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result.Value is NumericMetricValue numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"Metric '{result.Key}' scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_IsGroundedInContext()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync(
            scenarioName: "coach-grounded-response");

        var context = "The user is a software developer who works remotely and struggles with focus.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"Context: {context}"),
            new(ChatRole.User, "What techniques can help me stay focused during deep work?")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        scenario.Record(response);

        await scenario.EvaluateAsync();

        var results = scenario.GetEvaluationResults();
        if (results.TryGetValue("Groundedness", out var groundedness) &&
            groundedness is NumericMetricValue g)
        {
            Assert.IsTrue(g.Value >= 3.0, $"Groundedness scored {g.Value}, expected >= 3.0");
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts across multiple configurations
/// and persists results for cross-run comparison via the reporting storage.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string[] Prompts =
    [
        "Give me a 3-step plan to learn a new programming language.",
        "How should I prepare for a technical interview?",
        "Suggest a weekly exercise routine for desk workers."
    ];

    [TestMethod]
    public async Task CompareRuns_PersistResultsForDiff()
    {
        // Each test run is tagged with a unique execution ID.
        // The reporting storage accumulates results so you can compare across runs
        // (e.g., after a prompt change or model swap).
        var config = EvalConfig.CreateReportingConfig("compare");

        foreach (var prompt in Prompts)
        {
            await using var scenario = await config.CreateScenarioRunAsync(
                scenarioName: $"compare-{prompt[..20].Replace(' ', '-')}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, prompt)
            };

            var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
            scenario.Record(response);

            await scenario.EvaluateAsync();
        }

        // Results are persisted to .eval-results/ directory.
        // Use `dotnet test` with different env vars (model, deployment) to produce
        // comparison data, then inspect the JSON reports or render them.
        var resultsDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvalConfig).Assembly.Location)!,
            ".eval-results");

        Assert.IsTrue(Directory.Exists(resultsDir), "Results directory should be created.");
    }

    [TestMethod]
    public async Task CompareRuns_ScoresAreStable()
    {
        var config = EvalConfig.CreateReportingConfig("compare-stability");

        var prompt = "What are three benefits of code reviews?";
        var scores = new List<double>();

        // Run the same prompt twice to check score stability.
        for (int i = 0; i < 2; i++)
        {
            await using var scenario = await config.CreateScenarioRunAsync(
                scenarioName: $"stability-run-{i}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, prompt)
            };

            var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
            scenario.Record(response);

            await scenario.EvaluateAsync();

            var results = scenario.GetEvaluationResults();
            if (results.TryGetValue("Coherence", out var coherence) &&
                coherence is NumericMetricValue c)
            {
                scores.Add(c.Value);
            }
        }

        if (scores.Count == 2)
        {
            var drift = Math.Abs(scores[0] - scores[1]);
            Assert.IsTrue(drift <= 2.0,
                $"Score drift {drift} exceeds threshold. Run1={scores[0]}, Run2={scores[1]}");
        }
    }
}

