    /// </summary>
    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(ModelEndpoint), new Azure.AzureKeyCredential(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key"));

        return client
            .GetChatClient(ModelDeployment)
            .AsIChatClient()
            .AsBuilder()
            .UseOpenTelemetry()
            .Build();
    }

