            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
            new CompletenessEvaluator(),
        ];
    }

    /// <summary>
    /// Builds a ReportingConfiguration that persists results to disk for comparison across runs.
    /// </summary>
