    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvalConfig).Assembly.Location)!,
            ".eval-results");

        return new ReportingConfiguration(
            storageRootPath: storageDir,
            evaluators: GetQualityEvaluators(),
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            enableResponseCaching: true);
